import { DISCLAIMER } from '../../src/modules/reports/validators';

/**
 * Тексты подставной модели — руками, а не генератором.
 *
 * Зачем руками: конвейер проверяется валидаторами, и если «модель» отвечает
 * случайной строкой нужной длины, тест доказывает только то, что цикл
 * перегенерации умеет считать символы. Эти четыре раздела написаны так, как
 * должен отвечать продукт: без вердиктов, без процентов, без рода партнёра,
 * без астрологических терминов в первых 200 знаках и с тремя действиями в
 * конце.
 *
 * Объёмы: 715 / 802 / 638 / 462 знака — все внутри границ
 * `COMPAT_RANGES` (700–900, 700–900, 600–800, 400–550).
 */

function body(paragraphs: readonly (readonly string[])[]): string {
  return paragraphs.map((paragraph) => paragraph.join(' ')).join('\n\n');
}

