/** `steps` без подписи: подпись дописывает нормализатор, и в объём она не входит. */
export const COMPAT_STUB_STEPS_BODY = STEPS.join('\n\n');
export const COMPAT_STUB_STEPS = `${COMPAT_STUB_STEPS_BODY}\n\n${DISCLAIMER}`;

